[
  {
    "statement": "Farmland bee conservation studies have documented several cost-effective methods for creating bee-friendly habitats on farmland.",
    "citations": []
  },
  {
    "statement": "Sowing uncropped arable field margins with native wild flower seed mixes supports a higher abundance and species richness of foraging bumblebees compared to cropped field edges, grassy margins, or naturally regenerated uncropped margins.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Perennial leguminous herbs included in seed mixtures are important forage sources for bumblebees.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Perennial leguminous herbs are particularly important forage sources for long-tongued bumblebee species.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Agricultural nectar and pollen mixes sown on field margins attract significantly more foraging bumblebees than naturally regenerated, grassy, or cropped field margins.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Field margins sown with agricultural legume plants degrade in value to bumblebees and would need to be re-sown every few years.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Leaving arable field margins uncropped for natural regeneration provides benefits for bees.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "The value of naturally regenerated uncropped field margins is not consistent from year to year.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "The value of naturally regenerated uncropped field margins is often based on thistle species that are considered weeds.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "Planting dedicated floral resources, particularly phacelia, on farmland supports substantial numbers of wild bees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Studies have recorded 8 to 35 species of wild bees foraging on dedicated floral resources planted on farmland.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Reducing the intensity of farmland meadow management enhances the numbers and diversity of wild bees.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Delaying the first cuts of farmland meadows enhances the numbers and diversity of wild bees.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Reducing agrochemical use on farmland meadows enhances the numbers and diversity of wild bees.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "At a landscape scale, the abundance of long-tongued bumblebees on field margins is positively correlated with the number of pollen and nectar agri-environment agreements in the area.",
    "citations": [
      "362"
    ]
  }
]

[
  {
    "statement": "No evidence was found demonstrating the effects on wild bee communities of connecting patches of natural or semi-natural habitat.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "No evidence was found demonstrating the effects of restoring natural or semi-natural habitat on bee diversity or abundance in neighbouring farms.",
    "citations": [
      "6"
    ]
  },
  {
    "statement": "General studies on habitat connectivity for invertebrates show mixed results.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "Four studies from the Czech Republic, Germany and the Netherlands found some degree of colonization of connected areas by invertebrates.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "The colonization process of connected areas by invertebrates was found to be slow.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "The extent of colonization of connected areas varied between invertebrate taxa.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "None of the general studies on habitat connectivity for invertebrates specifically examined wild bee communities.",
    "citations": []
  },
  {
    "statement": "None of the general studies on habitat connectivity for invertebrates specifically examined wild bee communities' responses to habitat connectivity.",
    "citations": []
  }
]

[
  {
    "statement": "There is no evidence on the impact of retaining dead wood in forests or woodlands on wild bee communities or populations.",
    "citations": [
      "36"
    ]
  },
  {
    "statement": "No studies have been found that directly and quantitatively tested whether retaining dead wood during forest management helps conserve wild bee populations.",
    "citations": []
  },
  {
    "statement": "Artificial nest sites for solitary bees have been extensively studied.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Many species of solitary bee readily nest in provided nest boxes.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "The specific practice of retaining natural dead wood as habitat for wild bees has not been scientifically evaluated.",
    "citations": []
  }
]

[
  {
    "statement": "There is no direct research on the success rates for reintroducing laboratory-reared bumblebee queens specifically to the wild.",
    "citations": [
      "51"
    ]
  },
  {
    "statement": "Studies on reintroducing laboratory-reared bumblebee colonies provide relevant context.",
    "citations": []
  },
  {
    "statement": "Seven replicated trials monitored the success of laboratory-reared bumblebee colonies introduced to the environment.",
    "citations": []
  },
  {
    "statement": "Four of the seven trials allowed the laboratory-reared colonies to develop until new queens were produced or the founding queen died.",
    "citations": []
  },
  {
    "statement": "In two UK trials, the numbers of new queens produced per laboratory-reared colony were very low or zero.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Two other trials that allowed laboratory-reared colonies to develop produced good numbers of new queens.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "High rates of social parasitism by cuckoo bees were observed in released laboratory-reared bumblebee colonies.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Social parasitism rates by cuckoo bees in released colonies reached 25-66% in Canada and 79% in the UK.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Social parasitism in released bumblebee colonies was reduced by placing colonies in landscapes with intermediate nectar and pollen availability.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Social parasitism in released bumblebee colonies was reduced by releasing the colonies late in the season rather than early.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Studies show that the declining North American bumblebee species B. vagans and B. terricola can successfully rear adults in captivity.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "In all captive rearing trials for the bumblebee species B. fervidus, queens consistently laid eggs but the larvae died before becoming adults.",
    "citations": [
      "50"
    ]
  }
]

[
  {
    "statement": "Planting dedicated floral resources on farmland appears to be one of the most effective methods for supporting wild bee populations.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Trials in Europe and North America have recorded substantial numbers of wild bees foraging on perennial or annual sown flowering plants in agricultural environments.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Ten trials monitoring phacelia patches found substantial numbers of foraging wild bees, particularly bumblebees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "The number of foraging bee species found in the phacelia patch trials ranged from eight to 35.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Wild bird seed or cover mixtures show promise for supporting wild bees.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Seven UK studies found that wild bird seed or cover mixtures had positive effects on bee abundance or species richness.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Agri-environment schemes demonstrate mixed results for wild bee populations.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Four replicated trials in Europe showed enhanced diversity and/or abundance of foraging wild bees under various agri-environment schemes.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Swiss Ecological Compensation Areas and German organic farming options are examples of agri-environment schemes that enhanced wild bee populations.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Reducing the intensity of farmland meadow management shows some benefit for wild bees.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Two replicated trials found enhanced numbers and diversity of wild bees on meadows with a delayed first cut and little agrochemical use.",
    "citations": [
      "22"
    ]
  },
  {
    "statement": "Converting to organic farming produces equivocal results for wild bee populations.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Three replicated trials showed a higher abundance of wild bees under organic arable farming compared to conventional farming.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Grass strips at field margins have mixed evidence of effectiveness for wild bees.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "Three UK trials showed that grass strips at field margins provided some enhancement of bee abundance but had inconsistent effects on diversity.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "There is no captured evidence that increasing clover leys enhances wild bee populations.",
    "citations": [
      "16"
    ]
  },
  {
    "statement": "There is no captured evidence that introducing nest boxes stocked with solitary bees enhances wild bee populations.",
    "citations": [
      "81"
    ]
  }
]

[
  {
    "statement": "The available evidence provides limited direct comparison between connecting existing semi-natural habitats versus replanting native forest for boosting bee populations.",
    "citations": []
  },
  {
    "statement": "No evidence was found of the effects on wild bee communities of connecting patches of natural or semi-natural habitat.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "No evidence was found demonstrating the effects of restoring natural or semi-natural habitat on bee diversity or abundance in neighbouring farms.",
    "citations": [
      "6"
    ]
  },
  {
    "statement": "No evidence was captured for the effects of protecting areas of natural or semi-natural habitat on bee populations or communities.",
    "citations": [
      "5"
    ]
  },
  {
    "statement": "There is substantial evidence for the effectiveness of creating new flowering habitat.",
    "citations": []
  },
  {
    "statement": "Five replicated trials in the UK showed that uncropped field margins sown with wild flowers support a higher abundance and species richness of foraging bumblebees than cropped field edges, grassy margins or naturally regenerated uncropped margins.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Eighty individual studies investigated the effects of flowering strips on biodiversity.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Sixty-four studies showed that flowering strips provided some benefits to one or more wildlife groups.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Sixty-five studies reported effects of flowering strips on invertebrates.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Fifty studies reported positive effects from flowering strips on invertebrates.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Forty-one studies found evidence that flower strips had a positive influence on invertebrate numbers with increased abundance, species richness/diversity, or both.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Twenty-three studies evaluated the effects of planting nectar flower mixtures on butterflies and moths.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Multiple studies found that sown wildflower strips had higher species richness and diversity of butterflies and moths than conventional field margins, unsown margins, cropped fields or conventional grassland.",
    "citations": [
      "3932"
    ]
  }
]

[
  {
    "statement": "The available action documents do not contain specific information about how climate change impacts the nesting success of ground-nesting bees in the UK.",
    "citations": []
  },
  {
    "statement": "The action documents contain information about creating artificial nesting sites for ground-nesting bees.",
    "citations": [
      "13"
    ]
  },
  {
    "statement": "The action documents contain information about providing nest boxes for solitary bees and bumblebees.",
    "citations": [
      "47",
      "48",
      "80"
    ]
  },
  {
    "statement": "The action documents contain information about various pollination conservation strategies.",
    "citations": [
      "1406",
      "1407",
      "1408"
    ]
  },
  {
    "statement": "The action documents do not contain specific data or studies addressing climate change effects on ground-nesting bee nesting success in the UK.",
    "citations": []
  },
  {
    "statement": "The documents focus primarily on conservation interventions and the effectiveness of those interventions.",
    "citations": []
  },
  {
    "statement": "The documents' focus is not on climate change impacts on bee nesting behavior or success rates.",
    "citations": []
  }
]

[
  {
    "statement": "There is no specific percentage data available to compare bumblebee abundance between native wildflower seed mixes and agricultural nectar mixes on field margins.",
    "citations": []
  },
  {
    "statement": "The available evidence shows contradictory findings regarding bumblebee preference between native wildflower seed mixes and agricultural nectar mixes.",
    "citations": [
      "18",
      "19"
    ]
  },
  {
    "statement": "Three replicated trials showed that a mix of agricultural forage plants including legumes attracts greater numbers of bumblebees than a perennial wildflower mix in the first year.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "One small replicated trial showed that common long-tongued bumblebee species strongly preferred plots of perennial wildflower seed mix over a mix of annual forage plants.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Sowing either native wildflower mixes or agricultural nectar mixes leads to significantly higher bumblebee abundance compared to naturally regenerated, grassy, or cropped field margins.",
    "citations": [
      "18",
      "19"
    ]
  },
  {
    "statement": "No specific percentage increase is provided for the direct comparison of bumblebee abundance between native wildflower mixes and agricultural nectar mixes.",
    "citations": []
  }
]
